-- DISI rollback of Migration 058 (transaction-return bWAR evidence).
-- database/release/sql/rollback-058.sql, generated by database/research/058/build.mjs from the same research files as the migration.
--
-- Use only if a production failure requires it. One transaction, guarded. It restores the pre-058 logical state: the 91 team-season rows 058
-- added for the four returned players (Garland, Leyritz, Grant, Versalles) are RETRACTED with a stated reason (the 032 guard forbids deleting a
-- team-season fact; a retracted fact is sealed and is never read by a value view, a lineage or a queue), and the product snapshots are refreshed
-- once. Nothing else is touched: the 54 rows of Migration 057 stay ACTIVE, and the two shared 057 source rows stay as provenance. 058 can be applied
-- again afterwards: it inserts fresh ACTIVE rows beside the retracted ones.
--
-- Order and dependencies.
--   * 058 is rolled back before 057. After 058 has been applied once, rollback-057 refuses for good, even after this rollback: its guard treats
--     any row (ACTIVE or RETRACTED) of another player on the 057 sources as later research that depends on them, and the ledger never deletes.
--     The same holds for a re-run of the frozen 057: its postconditions count every row on those sources. This is the cost of reusing the 057
--     sources instead of registering the same files twice; it is accepted, and migration order is authoritative.
--   * rollback-050 was already unavailable after 057 (10 of its 11 players carry 057 team-season rows). rollback-055 and rollback-056 are
--     unaffected: none of the four belongs to their populations.

begin;

create temporary table _r058 on commit drop as
select $r058${"baseline":{"signings":[{"chain_status":"INCOMPLETE_WAR_NOT_LOADED","direct":"0.00","observable":"4.90","pkg_down":null,"pkg_first":"0.62","player_slug":"chico-fernandez","realized":"0.62","realized_value_state":"TO_DATE_CHAIN_INCOMPLETE","trade":"0.62"},{"chain_status":"INCOMPLETE_WAR_NOT_LOADED","direct":"0.19","observable":null,"pkg_down":null,"pkg_first":null,"player_slug":"jose-vizcaino","realized":"0.09","realized_value_state":"TO_DATE_CHAIN_INCOMPLETE","trade":"-0.10"},{"chain_status":"INCOMPLETE_WAR_NOT_LOADED","direct":"1.23","observable":null,"pkg_down":null,"pkg_first":null,"player_slug":"tony-abreu","realized":null,"realized_value_state":"VALUE_UNRESOLVED","trade":null}],"transaction_queue":[{"issue":"CASH_AMOUNT_UNKNOWN","items":17},{"issue":"DODGERS_RETURN_WITHOUT_RECORDED_ACQUISITION","items":5},{"issue":"DOWNSTREAM_WAR_NOT_LOADED","items":6},{"issue":"EXIT_NOT_RESEARCHED_DOWNSTREAM","items":5},{"issue":"EXIT_STATUS_UNVERIFIED","items":16},{"issue":"EXIT_TRANSACTION_MISSING","items":2},{"issue":"FUTURE_CONSIDERATIONS_UNRESOLVED","items":3},{"issue":"POOL_SPACE_AMOUNT_UNKNOWN","items":1},{"issue":"PTBNL_UNRESOLVED","items":2},{"issue":"RETURN_ASSET_EXIT_MISSING","items":1}],"value_queue":[{"issue":"ACQUISITION_COST_INCOMPLETE","items":28},{"issue":"DOWNSTREAM_ASSET_CHAIN_INCOMPLETE","items":8},{"issue":"LINEAGE_BOUNDARY_NOTED","items":22},{"issue":"OUTCOME_INCOMPLETE","items":8},{"issue":"TRADE_PACKAGE_ATTRIBUTION_UNRESOLVED","items":27}],"value_totals":{"realized":"297.60","resolved":87},"war_active":1934,"war_active_057":54},"bref_ids":["garlajo01","leyriji01","grantmu01","versazo01"],"rows":91,"source_urls":["https://web.archive.org/web/20260911214553id_/https://www.baseball-reference.com/data/war_daily_bat.txt","https://web.archive.org/web/20260210222101id_/https://www.baseball-reference.com/data/war_daily_pitch.txt"]}$r058$::jsonb as j;

create temporary table _r058_players on commit drop as
select x as bref_id from _r058, jsonb_array_elements_text(j -> 'bref_ids') x;

create temporary table _r058_sources on commit drop as
select so.id from public.sources so where so.url in (select jsonb_array_elements_text(j -> 'source_urls') from _r058);

create temporary table _r058_queue on commit drop as
select k as kind, x ->> 'issue' as issue, (x ->> 'items')::int as items
from _r058, lateral (values ('TX', j #> '{baseline,transaction_queue}'), ('VALUE', j #> '{baseline,value_queue}')) v(k, a), jsonb_array_elements(v.a) x;

create temporary table _r058_signings on commit drop as
select x ->> 'player_slug' as player_slug, x ->> 'realized_value_state' as realized_value_state, x ->> 'chain_status' as chain_status,
  (x ->> 'direct')::numeric as direct, (x ->> 'trade')::numeric as trade, (x ->> 'realized')::numeric as realized, (x ->> 'pkg_first')::numeric as pkg_first,
  (x ->> 'pkg_down')::numeric as pkg_down, (x ->> 'observable')::numeric as observable
from _r058, jsonb_array_elements(j #> '{baseline,signings}') x;

create temporary table _r058_before on commit drop as
select (select md5(string_agg(t, '|' order by t)) from (select w::text as t from public.player_mlb_team_season_war w
          where not (w.bref_id in (select bref_id from _r058_players) and w.source_id in (select id from _r058_sources))) x) as other_war_hash,
  (select md5(coalesce(string_agg(h, '' order by h), '')) from (select md5(to_jsonb(s)::text) as h from public.v_outcome_target_support s) z) as support,
  (select md5(coalesce(string_agg(h, '' order by h), '')) from (select md5(to_jsonb(e)::text) as h from public.v_outcome_model_evaluation e) z) as evaluation_view;

-- ===========================================================================
-- 1. GUARDS
-- ===========================================================================

do $$
begin
  if (select count(*) from _r058_sources) <> 2
     or not exists (select 1 from public.player_mlb_team_season_war w where w.source_id in (select id from _r058_sources) and w.record_status = 'ACTIVE'
                    and w.bref_id in (select bref_id from _r058_players)) then
    raise exception 'rollback-058: Migration 058 is not applied';
  end if;
  -- later research must not depend on what is retracted: no superseding fact, no other source's evidence for the four, exactly the 91 rows
  if exists (select 1 from public.player_mlb_team_season_war w where w.supersedes_record_id in (select id from public.player_mlb_team_season_war
               where source_id in (select id from _r058_sources) and bref_id in (select bref_id from _r058_players)))
     or exists (select 1 from public.player_mlb_team_season_war w where w.bref_id in (select bref_id from _r058_players)
                and w.source_id not in (select id from _r058_sources))
     or (select count(*) from public.player_mlb_team_season_war w where w.source_id in (select id from _r058_sources) and w.record_status = 'ACTIVE'
         and w.bref_id in (select bref_id from _r058_players)) <> (select (j ->> 'rows')::int from _r058) then
    raise exception 'rollback-058: later research depends on the 058 evidence (a superseding fact or another source''s rows for the four); rollback refused';
  end if;
end $$;

-- ===========================================================================
-- 2. RETRACT THE 058 TEAM-SEASON ROWS (the four returned players only; the 057 rows are never touched)
-- ===========================================================================

update public.player_mlb_team_season_war w set record_status = 'RETRACTED', retracted_at = now(),
  retraction_reason = 'Rollback of Migration 058 (transaction-return bWAR evidence): the archived-capture facts for the four returned players are withdrawn and the pre-058 state restored.'
where w.source_id in (select id from _r058_sources) and w.record_status = 'ACTIVE' and w.bref_id in (select bref_id from _r058_players);

-- ===========================================================================
-- 3. POSTCONDITIONS AND ONE REFRESH
-- ===========================================================================

do $$
declare
  b record;
begin
  select * into b from _r058_before;
  if exists (select 1 from public.player_mlb_team_season_war w where w.bref_id in (select bref_id from _r058_players) and w.record_status = 'ACTIVE')
     or (select count(*) from public.player_mlb_team_season_war where record_status = 'ACTIVE') <> (select (j #>> '{baseline,war_active}')::int from _r058)
     or (select count(*) from public.player_mlb_team_season_war w where w.source_id in (select id from _r058_sources) and w.record_status = 'ACTIVE')
        <> (select (j #>> '{baseline,war_active_057}')::int from _r058)
     or b.other_war_hash is distinct from (select md5(string_agg(t, '|' order by t)) from (select w::text as t from public.player_mlb_team_season_war w
          where not (w.bref_id in (select bref_id from _r058_players) and w.source_id in (select id from _r058_sources))) x) then
    raise exception 'rollback-058 postcondition: the pre-058 active team-season rows are not restored exactly (the 057 rows and every earlier row untouched)';
  end if;
  if exists (select s.player_slug, s.realized_value_state, s.chain_status, s.direct_dodgers_bwar, s.individually_attributable_trade_bwar, s.realized_org_value_bwar,
               s.package_first_hop_participation_bwar, s.package_downstream_participation_bwar, s.observable_not_attributable_bwar
             from public.v_player_realized_organizational_value s where s.player_slug in (select player_slug from _r058_signings)
             except select player_slug, realized_value_state, chain_status, direct, trade, realized, pkg_first, pkg_down, observable from _r058_signings)
     or (select row(count(*) filter (where realized_org_value_bwar is not null), sum(realized_org_value_bwar)::numeric) from public.v_player_realized_organizational_value)
        is distinct from (select row((j #>> '{baseline,value_totals,resolved}')::bigint, (j #>> '{baseline,value_totals,realized}')::numeric) from _r058) then
    raise exception 'rollback-058 postcondition: the realized value is not the pre-058 state (297.60 bWAR, 87 signings)';
  end if;
  if exists ((select issue, count(*)::int from public.v_transaction_research_queue group by 1) except select issue, items from _r058_queue where kind = 'TX')
     or exists (select issue, items from _r058_queue where kind = 'TX' except (select issue, count(*)::int from public.v_transaction_research_queue group by 1))
     or exists ((select issue, count(*)::int from public.v_value_research_queue group by 1) except select issue, items from _r058_queue where kind = 'VALUE')
     or exists (select issue, items from _r058_queue where kind = 'VALUE' except (select issue, count(*)::int from public.v_value_research_queue group by 1)) then
    raise exception 'rollback-058 postcondition: the transaction or value research queue is not the pre-058 state';
  end if;
  if b.support is distinct from (select md5(coalesce(string_agg(h, '' order by h), '')) from (select md5(to_jsonb(s)::text) as h from public.v_outcome_target_support s) z)
     or b.evaluation_view is distinct from (select md5(coalesce(string_agg(h, '' order by h), '')) from (select md5(to_jsonb(e)::text) as h from public.v_outcome_model_evaluation e) z) then
    raise exception 'rollback-058 postcondition: the prediction layer moved';
  end if;
end $$;

select * from public.disi_refresh_product_snapshots();

commit;
